MAX_YAML_BYTES = 1024 * 1024
_CONTROLLER_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}\.ya?ml$")
_BT_ADDRESS_RE = re.compile(r"^[0-9A-Fa-f]{2}(?::[0-9A-Fa-f]{2}){5}$")
_BT_ANSI_ESCAPE_RE = re.compile(r"\x1b(?:[@-Z\\-_]|\[[0-?]*[ -/]*[@-~])")
_BT_PROMPT_RE = re.compile(r"^(?:\[[^\]]+\])?#\s*$", re.IGNORECASE)
_BT_PAIRING_AGENT_CAPABILITY = "NoInputNoOutput"
_BT_PAIRING_AGENT_OUTPUT_LIMIT = 16384


def _clean_bluetoothctl_output(value: Any) -> str:
    """Remove readline/ANSI noise emitted by bluetoothctl on pipes."""
    text = _BT_ANSI_ESCAPE_RE.sub("", str(value or ""))
    return text.replace("\x01", "").replace("\x02", "").replace("\r", "")


class _BluetoothctlPairingAgent:
    """Long-lived bluetoothctl agent used for deterministic pairing.

    BlueZ must finish registering the requested capability before `pair` is
    sent. Writing `agent`, `default-agent`, and `pair` back-to-back can race
    registration and leave an interactive DisplayYesNo agent handling the
    request, which a headless web action cannot answer.
    """

    _AUTO_ACCEPT_PROMPTS: Sequence[str] = (
        "confirm passkey",
        "accept pairing",
        "request authorization",
        "authorize service",
    )

    def __init__(self, executable: str) -> None:
        self._condition = threading.Condition()
        self._write_lock = threading.Lock()
        self._output = ""
        self._prompt_offsets: Dict[str, int] = {}
        self.process = subprocess.Popen(
            [str(executable), f"--agent={_BT_PAIRING_AGENT_CAPABILITY}"],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1,
            env={**os.environ, "LC_ALL": "C"},
            start_new_session=False,
        )
        self._reader = threading.Thread(
            target=self._read_output,
            name="puddleduck-bluetooth-agent-output",
            daemon=True,
        )
        self._reader.start()

    def _read_output(self) -> None:
        stream = self.process.stdout
        if stream is None:
            return
        while True:
            character = stream.read(1)
            if character == "":
                break
            command: Optional[str] = None
            with self._condition:
                self._output = (self._output + character)[-_BT_PAIRING_AGENT_OUTPUT_LIMIT:]
                cleaned = _clean_bluetoothctl_output(self._output)
                lowered = cleaned.lower()
                for prompt in self._AUTO_ACCEPT_PROMPTS:
                    position = lowered.rfind(prompt)
                    if position < 0 or position <= self._prompt_offsets.get(prompt, -1):
                        continue
                    tail = lowered[position:]
                    if "yes/no" in tail or prompt in {"request authorization", "authorize service"}:
                        self._prompt_offsets[prompt] = position
                        command = "yes"
                        break
                self._condition.notify_all()
            if command:
                try:
                    self.send(command)
                except Exception:
                    return
        with self._condition:
            self._condition.notify_all()

    def transcript(self) -> str:
        with self._condition:
            return _clean_bluetoothctl_output(self._output).strip()

    def send(self, command: str) -> None:
        if self.process.poll() is not None:
            raise RuntimeError(
                f"bluetoothctl pairing agent exited with status {self.process.returncode}: "
                f"{self.transcript()[-1000:]}"
            )
        if self.process.stdin is None:
            raise RuntimeError("bluetoothctl pairing agent stdin is unavailable")
        with self._write_lock:
            self.process.stdin.write(str(command) + "\n")
            self.process.stdin.flush()

    def wait_for(self, needles: Sequence[str], *, timeout: float, description: str) -> str:
        wanted = tuple(str(value).lower() for value in needles)
        deadline = time.monotonic() + max(0.1, float(timeout))
        with self._condition:
            while True:
                output = _clean_bluetoothctl_output(self._output)
                lowered = output.lower()
                if any(value in lowered for value in wanted):
                    return output
                if self.process.poll() is not None:
                    raise RuntimeError(
                        f"bluetoothctl exited before {description}: "
                        f"{output.strip()[-1000:] or self.process.returncode}"
                    )
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise RuntimeError(
                        f"timed out waiting for {description}: "
                        f"{output.strip()[-1000:] or 'no bluetoothctl output'}"
                    )
                self._condition.wait(min(0.2, remaining))

    def register_default(self) -> None:
        self.wait_for(
            ("agent registered",),
            timeout=8.0,
            description=f"{_BT_PAIRING_AGENT_CAPABILITY} agent registration",
        )
        self.send("default-agent")
        self.wait_for(
            ("default agent request successful", "default agent successfully registered"),
            timeout=8.0,
            description="default pairing agent registration",
        )

    def close(self) -> None:
        if self.process.poll() is None:
            try:
                self.send("agent off")
                self.send("quit")
            except Exception:
                pass
        try:
            self.process.wait(timeout=2.0)
        except subprocess.TimeoutExpired:
            self.process.terminate()
            try:
                self.process.wait(timeout=2.0)
            except subprocess.TimeoutExpired:
                self.process.kill()
        if self._reader.is_alive():
            self._reader.join(timeout=1.0)


def _template_text(name: str, fallback: str) -> str:
    path = Path(__file__).resolve().parent / "templates" / name
    try:
        return path.read_text(encoding="utf-8")
    except Exception:
        return fallback


ACTIONS_TEMPLATE = _template_text(
    "duck_actions.yaml",
    "actions:\n  - name: RLWalk\n    trigger: start\n    mode: long\n    cmd:\n      - /home/duck/walk.sh\n    cooldown_s: 0.5\n",
)
DUCK_CONTROL_TEMPLATE = _template_text(
    "duck_control.yaml",
    "duckdrive: {}\nducksense: {}\n",
)
TRIGGERS_TEMPLATE = _template_text(
    "duck_triggers.yaml",
    "defaults:\n  event: press\n  cooldown_s: 0.10\n  target: head\ntriggers: {}\n",
)
CONTROLLER_TEMPLATE = """controllers:
  - device: 'Controller device name'
    name: 'Friendly controller name'
    buttons:
      0: 'A'
    axes:
      0: -lin_vel_x
      1: ang_vel
"""


def _read_text(path: Path) -> str:
    data = path.read_bytes()
    if len(data) > MAX_YAML_BYTES:
        raise ValueError(f"{path.name} is larger than {MAX_YAML_BYTES} bytes")
    return data.decode("utf-8")


def _atomic_write_text(path: Path, text: str, *, mode: int = 0o600) -> None:
    encoded = text.encode("utf-8")
    if len(encoded) > MAX_YAML_BYTES:
        raise ValueError(f"YAML is larger than {MAX_YAML_BYTES} bytes")
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp_name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=str(path.parent))
    try:
        os.fchmod(fd, mode)
        with os.fdopen(fd, "wb", closefd=True) as stream:
            stream.write(encoded)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(tmp_name, path)
        try:
            os.chmod(path, mode)
        except OSError:
            pass
    except Exception:
        try:
            os.close(fd)
        except OSError:
            pass
        try:
            os.unlink(tmp_name)
        except OSError:
            pass
        raise


def _load_mapping(text: str, *, label: str) -> Dict[str, Any]:
    if not isinstance(text, str):
        raise ValueError(f"{label} YAML must be text")
    if len(text.encode("utf-8")) > MAX_YAML_BYTES:
        raise ValueError(f"{label} YAML is larger than {MAX_YAML_BYTES} bytes")
    try:
        parsed = yaml.safe_load(text)
    except yaml.YAMLError as exc:
        mark = getattr(exc, "problem_mark", None)
        where = f" at line {mark.line + 1}, column {mark.column + 1}" if mark is not None else ""
        problem = getattr(exc, "problem", None) or str(exc)
        raise ValueError(f"Invalid {label} YAML{where}: {problem}") from exc
    if parsed is None:
        parsed = {}
    if not isinstance(parsed, dict):
        raise ValueError(f"{label} YAML root must be a mapping")
    return parsed


def _file_meta(path: Path) -> Dict[str, Any]:
    try:
        st = path.stat()
    except FileNotFoundError:
        return {"exists": False, "bytes": 0, "modified": None}
    return {
        "exists": True,
        "bytes": int(st.st_size),
        "modified": float(st.st_mtime),
    }


class PuddleDuckConfigStore:
    """Validated access to the operator-owned YAML files in ``$HOME``."""

    def __init__(
        self,
        *,
        actions_path: Optional[str] = None,
        duck_control_path: Optional[str] = None,
        triggers_path: Optional[str] = None,
        controllers_dir: Optional[str] = None,
        builtin_controllers_dir: Optional[str] = None,
        on_actions_changed: Optional[Callable[[], Any]] = None,
        on_triggers_changed: Optional[Callable[[], Any]] = None,
    ):
        self.actions_path = Path(actions_path or "~/duck_actions.yaml").expanduser()
        self.duck_control_path = Path(duck_control_path or "~/duck_control.yaml").expanduser()
        self.triggers_path = Path(triggers_path or "~/duck_triggers.yaml").expanduser()
        self.controllers_dir = Path(controllers_dir or "~/controllers").expanduser()
        if builtin_controllers_dir:
            self.builtin_controllers_dir = Path(builtin_controllers_dir).expanduser()
        else:
            self.builtin_controllers_dir = Path(__file__).resolve().parents[1] / "common" / "controllers"
        self._on_actions_changed = on_actions_changed
        self._on_triggers_changed = on_triggers_changed
        self._lock = threading.RLock()

    @staticmethod
    def _validate_actions(text: str) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
        doc = _load_mapping(text, label="duck_actions")
        actions = doc.get("actions", [])
        if actions is None:
            actions = []
        if not isinstance(actions, list):
            raise ValueError("duck_actions.yaml 'actions' must be a list")
        summary: List[Dict[str, Any]] = []
        names = set()
        for index, action in enumerate(actions):
            if not isinstance(action, dict):
                raise ValueError(f"actions[{index}] must be a mapping")
            name = str(action.get("name") or "").strip()
            trigger = action.get("trigger")
            command = action.get("cmd")
            if not name:
                raise ValueError(f"actions[{index}] is missing name")
            if name in names:
                raise ValueError(f"duplicate action name: {name}")
            names.add(name)
            if trigger is None or str(trigger).strip() == "":
                raise ValueError(f"action {name!r} is missing trigger")
            if not isinstance(command, (str, list)) or (isinstance(command, list) and not command):
                raise ValueError(f"action {name!r} must have a non-empty cmd")
            if isinstance(command, list) and not all(isinstance(part, (str, int, float)) for part in command):
                raise ValueError(f"action {name!r} cmd list must contain scalar values")
            command_text = command if isinstance(command, str) else " ".join(str(v) for v in command)
            summary.append({
                "index": index,
                "name": name,
                "trigger": str(trigger),
                "mode": str(action.get("mode") or "short"),
                "command": command_text,
                "toggle": bool(action.get("toggle", False)),
            })
        return doc, summary

    @staticmethod
    def _validate_duck_control(text: str) -> Dict[str, Any]:
        doc = _load_mapping(text, label="duck_control")
        for key in ("duckdrive", "ducksense"):
            value = doc.get(key)
            if value is not None and not isinstance(value, dict):
                raise ValueError(f"duck_control.yaml '{key}' must be a mapping")
        return doc


    @staticmethod
    def _validate_triggers(text: str) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
        document, definition = parse_trigger_yaml(text)
        return document, definition.summary()

    @staticmethod
    def _validate_controller(text: str) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
        doc = _load_mapping(text, label="controller")
        controllers = doc.get("controllers", [])
        gestures = doc.get("gestures", [])
        if not isinstance(controllers, list):
            raise ValueError("controller YAML 'controllers' must be a list")
        if gestures is not None and not isinstance(gestures, list):
            raise ValueError("controller YAML 'gestures' must be a list")
        summary: List[Dict[str, Any]] = []
        for index, item in enumerate(controllers):
            if not isinstance(item, dict):
                raise ValueError(f"controllers[{index}] must be a mapping")
            device = str(item.get("device") or "").strip()
            if not device:
                raise ValueError(f"controllers[{index}] is missing device")
            buttons = item.get("buttons", {}) or {}
            axes = item.get("axes", {}) or {}
            if not isinstance(buttons, dict) or not isinstance(axes, dict):
                raise ValueError(f"controller {device!r} buttons and axes must be mappings")
            for label, mapping in (("button", buttons), ("axis", axes)):
                for raw_key in mapping:
                    try:
                        int(raw_key)
                    except Exception as exc:
                        raise ValueError(f"controller {device!r} {label} key {raw_key!r} is not an integer") from exc
            kyberpad = item.get("kyberpad")
            kyberpad_summary = None
            if kyberpad is not None:
                normalized_kyberpad = validate_kyberpad(kyberpad)
                export_ready = all(key in normalized_kyberpad for key in ("general", "buttons", "pwm"))
                kyberpad_summary = {
                    "export_ready": export_ready,
                    "button_count": len(normalized_kyberpad.get("buttons") or []),
                    "pwm_count": len((normalized_kyberpad.get("pwm") or {}).get("values") or []),
                }
            summary.append({
                "index": index,
                "device": device,
                "name": str(item.get("name") or device),
                "buttons": len(buttons),
                "axes": len(axes),
                "kyberpad": kyberpad_summary,
            })
        if not controllers and not gestures:
            raise ValueError("controller YAML must define at least one controller or gesture")
        return doc, summary

    def actions(self) -> Dict[str, Any]:
        with self._lock:
            meta = _file_meta(self.actions_path)
            text = _read_text(self.actions_path) if meta["exists"] else ACTIONS_TEMPLATE
            _, summary = self._validate_actions(text)
            return {
                "ok": True,
                "path": str(self.actions_path),
                "yaml": text,
                "template": not bool(meta["exists"]),
                "actions": summary,
                **meta,
            }

    def write_actions(self, text: str) -> Dict[str, Any]:
        self._validate_actions(text)
        with self._lock:
            _atomic_write_text(self.actions_path, text)
            reload_status = None
            if self._on_actions_changed is not None:
                try:
                    reload_status = self._on_actions_changed()
                except Exception as exc:
                    reload_status = {"ok": False, "message": f"saved, but live reload failed: {exc}"}
            result = self.actions()
            result["message"] = "duck_actions.yaml saved"
            if reload_status is not None:
                result["reload"] = reload_status
            return result

    def delete_actions(self) -> Dict[str, Any]:
        with self._lock:
            try:
                self.actions_path.unlink()
            except FileNotFoundError:
                pass
            reload_status = None
            if self._on_actions_changed is not None:
                try:
                    reload_status = self._on_actions_changed()
                except Exception as exc:
                    reload_status = {"ok": False, "message": f"deleted, but live reload failed: {exc}"}
            result = self.actions()
            result["message"] = "duck_actions.yaml deleted; template shown"
            if reload_status is not None:
                result["reload"] = reload_status
            return result

    def duck_control(self) -> Dict[str, Any]:
        with self._lock:
            meta = _file_meta(self.duck_control_path)
            text = _read_text(self.duck_control_path) if meta["exists"] else DUCK_CONTROL_TEMPLATE
            doc = self._validate_duck_control(text)
            return {
                "ok": True,
                "path": str(self.duck_control_path),
                "yaml": text,
                "template": not bool(meta["exists"]),
                "sections": sorted(str(k) for k in doc.keys()),
                **meta,
            }

    def write_duck_control(self, text: str) -> Dict[str, Any]:
        self._validate_duck_control(text)
        with self._lock:
            _atomic_write_text(self.duck_control_path, text)
            result = self.duck_control()
            result["message"] = "duck_control.yaml saved; it will be used the next time RLWalk starts"
            return result

    def delete_duck_control(self) -> Dict[str, Any]:
        with self._lock:
            try:
                self.duck_control_path.unlink()
            except FileNotFoundError:
                pass
            result = self.duck_control()
            result["message"] = "duck_control.yaml deleted; defaults will be used"
            return result

    def triggers(self) -> Dict[str, Any]:
        with self._lock:
            meta = _file_meta(self.triggers_path)
            text = _read_text(self.triggers_path) if meta["exists"] else TRIGGERS_TEMPLATE
            _, summary = self._validate_triggers(text)
            return {
                "ok": True,
                "path": str(self.triggers_path),
                "yaml": text,
                "template": not bool(meta["exists"]),
                "triggers": summary,
                **meta,
            }

    def write_triggers(self, text: str) -> Dict[str, Any]:
        self._validate_triggers(text)
        with self._lock:
            _atomic_write_text(self.triggers_path, text)
            reload_status = None
            if self._on_triggers_changed is not None:
                try:
                    reload_status = self._on_triggers_changed()
                except Exception as exc:
                    reload_status = {"ok": False, "message": f"saved, but live reload failed: {exc}"}
            result = self.triggers()
            result["message"] = "duck_triggers.yaml saved"
            if reload_status is not None:
                result["reload"] = reload_status
            return result

    def delete_triggers(self) -> Dict[str, Any]:
        with self._lock:
            _atomic_write_text(self.triggers_path, TRIGGERS_TEMPLATE)
            reload_status = None
            if self._on_triggers_changed is not None:
                try:
                    reload_status = self._on_triggers_changed()
                except Exception as exc:
                    reload_status = {"ok": False, "message": f"deleted, but live reload failed: {exc}"}
            result = self.triggers()
            result["message"] = "duck_triggers.yaml restored to the default template"
            if reload_status is not None:
                result["reload"] = reload_status
            return result

    @staticmethod
    def _controller_name(name: str) -> str:
        value = Path(str(name or "").strip()).name
        if value != str(name or "").strip() or not _CONTROLLER_NAME_RE.fullmatch(value):
            raise ValueError("controller filename must end in .yaml or .yml and contain only letters, digits, '.', '_' or '-'")
        return value

    def _controller_paths(self, name: str) -> Tuple[Path, Path]:
        safe = self._controller_name(name)
        return self.controllers_dir / safe, self.builtin_controllers_dir / safe

    def list_controllers(self) -> Dict[str, Any]:
        with self._lock:
            names = set()
            for root in (self.builtin_controllers_dir, self.controllers_dir):
                try:
                    names.update(p.name for p in root.iterdir() if p.is_file() and _CONTROLLER_NAME_RE.fullmatch(p.name))
                except FileNotFoundError:
                    pass
            items = []
            for name in sorted(names, key=str.lower):
                user, builtin = self._controller_paths(name)
                effective = user if user.is_file() else builtin
                source = "user" if user.is_file() else "built-in"
                try:
                    text = _read_text(effective)
                    _, summary = self._validate_controller(text)
                    error = ""
                except Exception as exc:
                    summary = []
                    error = str(exc)
                meta = _file_meta(effective)
                items.append({
                    "name": name,
                    "source": source,
                    "override": user.is_file() and builtin.is_file(),
                    "built_in": builtin.is_file(),
                    "controllers": summary,
                    "error": error,
                    **meta,
                })
            return {
                "ok": True,
                "directory": str(self.controllers_dir),
                "built_in_directory": str(self.builtin_controllers_dir),
                "controllers": items,
            }

    def controller(self, name: str) -> Dict[str, Any]:
        with self._lock:
            user, builtin = self._controller_paths(name)
            if user.is_file():
                path, source = user, "user"
            elif builtin.is_file():
                path, source = builtin, "built-in"
            else:
                return {
                    "ok": True,
                    "name": self._controller_name(name),
                    "path": str(user),
                    "source": "new",
                    "override": False,
                    "built_in": False,
                    "template": True,
                    "yaml": CONTROLLER_TEMPLATE,
                    "controllers": [],
                    "exists": False,
                    "bytes": 0,
                    "modified": None,
                }
            text = _read_text(path)
            _, summary = self._validate_controller(text)
            return {
                "ok": True,
                "name": path.name,
                "path": str(path),
                "write_path": str(user),
                "source": source,
                "override": user.is_file() and builtin.is_file(),
                "built_in": builtin.is_file(),
                "template": False,
                "yaml": text,
                "controllers": summary,
                **_file_meta(path),
            }

    def write_controller(self, name: str, text: str) -> Dict[str, Any]:
        safe = self._controller_name(name)
        self._validate_controller(text)
        with self._lock:
            user, _ = self._controller_paths(safe)
            _atomic_write_text(user, text)
            result = self.controller(safe)
            result["message"] = f"{safe} saved; restart the state service and any running policy to reload controller definitions"
            return result

    def export_controller_kyberpad(
        self,
        name: str,
        text: str,
        *,
        controller_index: int = 0,
    ) -> Dict[str, Any]:
        """Render one controller's KyberPad metadata as a v3.0 INI file.

        ``text`` is the current editor content rather than necessarily the
        saved file, so operators can inspect or download an unsaved KyberPad
        design before deciding whether to save the controller override.
        """
        safe = self._controller_name(name)
        doc, summary = self._validate_controller(text)
        controllers = doc.get("controllers") or []
        candidates = [
            (index, item)
            for index, item in enumerate(controllers)
            if isinstance(item, dict) and item.get("kyberpad") is not None
        ]
        if not candidates:
            raise ValueError("the selected controller YAML does not define a kyberpad mapping")

        try:
            requested = int(controller_index)
        except (TypeError, ValueError) as exc:
            raise ValueError("controller_index must be an integer") from exc

        selected = None
        for index, item in candidates:
            if index == requested:
                selected = (index, item)
                break
        if selected is None:
            # The UI sends the actual controller index. For one-controller
            # files, accepting zero keeps the request intuitive.
            if requested == 0 and len(candidates) == 1:
                selected = candidates[0]
            else:
                raise ValueError("the selected controller does not define a kyberpad mapping")

        index, controller = selected
        controller_name = str(controller.get("name") or controller.get("device") or f"controller {index + 1}")
        content = export_kyberpad_ini(controller.get("kyberpad"))
        return {
            "ok": True,
            "name": safe,
            "controller_index": index,
            "controller": controller_name,
            "filename": kyberpad_export_filename(safe, controller_name),
            "content": content,
            "bytes": len(content.encode("utf-8")),
            "kyberpads": [
                {
                    "index": item_index,
                    "device": str(item.get("device") or ""),
                    "name": str(item.get("name") or item.get("device") or f"controller {item_index + 1}"),
                }
                for item_index, item in candidates
            ],
        }

    def delete_controller(self, name: str) -> Dict[str, Any]:
        safe = self._controller_name(name)
        with self._lock:
            user, builtin = self._controller_paths(safe)
            if not user.is_file():
                if builtin.is_file():
                    raise ValueError("the built-in definition is read-only; edit it to create an override")
                raise FileNotFoundError(safe)
            user.unlink()
            if builtin.is_file():
                result = self.controller(safe)
                result["message"] = f"user override removed; {safe} now uses the built-in definition"
                return result
            return {"ok": True, "name": safe, "deleted": True, "message": f"{safe} deleted"}

    @staticmethod
    def _device_key(value: Any) -> str:
        return " ".join(str(value or "").split()).casefold()

    def _controller_definitions_locked(self) -> Dict[str, Dict[str, Any]]:
        """Return controller definitions keyed by exact device name.

        Built-in files are read first and user files second, matching PuddleJoy;
        a user definition for the same device therefore wins regardless of its
        filename.
        """
        definitions: Dict[str, Dict[str, Any]] = {}
        for root, source in (
            (self.builtin_controllers_dir, "built-in"),
            (self.controllers_dir, "user"),
        ):
            try:
                paths = sorted(
                    (
                        item for item in root.iterdir()
                        if item.is_file() and _CONTROLLER_NAME_RE.fullmatch(item.name)
                    ),
                    key=lambda item: item.name.lower(),
                )
            except FileNotFoundError:
                paths = []
            for path in paths:
                try:
                    doc = _load_mapping(_read_text(path), label="controller")
                except Exception:
                    continue
                for item in doc.get("controllers", []) or []:
                    if not isinstance(item, dict):
                        continue
                    device = str(item.get("device") or "").strip()
                    key = self._device_key(device)
                    if not key:
                        continue
                    definitions[key] = {
                        "device": device,
                        "name": str(item.get("name") or device),
                        "filename": path.name,
                        "path": str(path),
                        "source": source,
                    }
        return definitions

    @staticmethod
    def _controller_filename_slug(device_name: str) -> str:
        slug = re.sub(r"[^a-z0-9]+", "-", str(device_name or "").casefold()).strip("-")
        slug = slug[:96].rstrip("-") or "bluetooth-controller"
        return slug

    def ensure_bluetooth_controller_template(self, device: Dict[str, Any]) -> Dict[str, Any]:
        """Create a safe, empty mapping for a newly paired controller type.

        The controller *type* is the BlueZ device name/alias, not its MAC
        address. Pairing a second controller of the same model therefore reuses
        the existing YAML definition instead of creating another file.
        """
        device_name = " ".join(str(device.get("name") or device.get("alias") or "").split())
        alias = " ".join(str(device.get("alias") or device_name).split())
        address = str(device.get("address") or "").strip().upper()
        if not device_name:
            raise ValueError("paired controller did not report a device name")

        candidates = {self._device_key(device_name), self._device_key(alias)} - {""}
        with self._lock:
            definitions = self._controller_definitions_locked()
            for key in candidates:
                existing = definitions.get(key)
                if existing:
                    return {
                        "ok": True,
                        "created": False,
                        **existing,
                        "message": f"controller mapping already exists in {existing['filename']}",
                    }

            base = self._controller_filename_slug(device_name)
            filename = f"{base}.yaml"
            user, builtin = self._controller_paths(filename)
            if user.exists() or builtin.exists():
                suffix = re.sub(r"[^0-9a-f]", "", address.casefold())[-6:] or "paired"
                filename = f"{base}-{suffix}.yaml"
                user, builtin = self._controller_paths(filename)
                serial = 2
                while user.exists() or builtin.exists():
                    filename = f"{base}-{suffix}-{serial}.yaml"
                    user, builtin = self._controller_paths(filename)
                    serial += 1

            document = {
                "controllers": [{
                    "device": device_name,
                    "name": alias or device_name,
                    "buttons": {},
                    "axes": {},
                }],
            }
            header = (
                f"# Generated when Bluetooth controller {device_name!r} was paired.\n"
                + (f"# Bluetooth address at creation: {address}\n" if address else "")
                + "# Fill in button and axis mappings, then restart the state service and any running policy.\n"
            )
            text = header + yaml.safe_dump(
                document,
                sort_keys=False,
                default_flow_style=False,
                allow_unicode=True,
            )
            self._validate_controller(text)
            _atomic_write_text(user, text)
            result = self.controller(filename)
            result.update({
                "created": True,
                "device": device_name,
                "message": f"created controller mapping template {filename}",
            })
            return result



EMBEDDED_EMOTE_PROJECT_FIELDS = (
    "duckmation_project",
    "automagerie_project",  # Legacy bundled projects remain editable.
)
EDITABLE_EMOTE_PROJECT_FORMATS = {
    "duckmation_emote_keyframes_v1",
    "automagerie_emote_keyframes_v1",
    "automagerie_emote_keyframes_v2",
    "automagerie_emote_keyframes_v3",
}


_EMOTE_FILE_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._ ()+-]{0,159}\.json$")
MAX_EMOTE_BYTES = 16 * 1024 * 1024


class EmoteLibrary:
    """User and packaged ``darkwing_emote_control_v1`` clips.

    User clips live in ``$HOME/emotes``. Packaged clips are read-only defaults.
    A user clip with the same internal emote name overrides the packaged clip,
    matching DuckDrive's search order.
    """

    def __init__(self, root: Optional[str] = None, standard_root: Optional[str] = None):
        self.root = Path(root or "~/emotes").expanduser().resolve()
        self.standard_root = Path(
            standard_root
            or (Path(__file__).resolve().parents[1] / "common" / "emotes")
        ).expanduser().resolve()
        self.root.mkdir(parents=True, exist_ok=True)
        self._lock = threading.RLock()
        self._cache: Dict[Tuple[str, int, int, int, int], Dict[str, Any]] = {}

    @staticmethod
    def _filename(value: Any) -> str:
        name = str(value or "").strip()
        if not _EMOTE_FILE_RE.fullmatch(name) or Path(name).name != name:
            raise ValueError("emote filename must be a simple .json filename")
        return name

    @classmethod
    def preview_filename(cls, value: Any) -> str:
        name = cls._filename(value)
        return f"{Path(name).stem}.preview.mp4"

    @classmethod
    def preview_path_for(cls, path: Path) -> Path:
        return path.with_name(f"{path.stem}.preview.mp4")

    def _user_path(self, value: Any) -> Tuple[str, Path]:
        name = self._filename(value)
        return name, self.root / name

    def _source_path(self, source: Any, value: Any) -> Tuple[str, str, Path]:
        source_name = str(source or "").strip().lower()
        if source_name not in ("user", "standard"):
            raise ValueError("emote source must be user or standard")
        name = self._filename(value)
        root = self.root if source_name == "user" else self.standard_root
        return source_name, name, root / name

    @staticmethod
    def _document(path: Path) -> Dict[str, Any]:
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"invalid emote JSON at line {exc.lineno}, column {exc.colno}: {exc.msg}"
            ) from exc
        if not isinstance(value, dict):
            raise ValueError("emote JSON root must be an object")
        return value

    @classmethod
    def _validate_path(cls, path: Path):
        clip = EmotePlayer._load_clip(path)
        if clip is None:
            raise ValueError(f"emote format must be {EMOTE_FORMAT!r}")
        return clip, cls._document(path)

    def _item(self, path: Path, source: str) -> Dict[str, Any]:
        stat = path.stat()
        preview_path = self.preview_path_for(path)
        preview_stat = (
            preview_path.stat()
            if preview_path.is_file() and not preview_path.is_symlink()
            else None
        )
        cache_key = (
            str(path),
            int(stat.st_mtime_ns),
            int(stat.st_size),
            int(preview_stat.st_mtime_ns) if preview_stat is not None else 0,
            int(preview_stat.st_size) if preview_stat is not None else 0,
        )
        cached = self._cache.get(cache_key)
        if cached is not None:
            return dict(cached)
        clip, document = self._validate_path(path)
        encoded = quote(path.name, safe="")
        embedded_project = next(
            (
                document.get(field)
                for field in EMBEDDED_EMOTE_PROJECT_FIELDS
                if isinstance(document.get(field), dict)
            ),
            None,
        )
        editor_project_format = (
            str(embedded_project.get("format") or "")
            if isinstance(embedded_project, dict)
            else ""
        )
        editable = editor_project_format in EDITABLE_EMOTE_PROJECT_FORMATS
        item = {
            "filename": path.name,
            "name": clip.name,
            "source": source,
            "standard": source == "standard",
            "read_only": source == "standard",
            "author": str(document.get("author") or ""),
            "description": str(document.get("description") or ""),
            "format": str(document.get("format") or ""),
            "editable": editable,
            "editor_project_format": editor_project_format if editable else "",
            "rate_hz": float(clip.rate_hz),
            "duration_s": float(clip.duration_s),
            "declared_duration_s": clip.declared_duration_s,
            "frame_count": len(clip.frames),
            "channels": list(clip.channels),
            "units": dict(clip.units),
            "whole_sequence": dict(clip.whole_sequence),
            "feet_planted": bool(clip.feet_planted),
            "bytes": int(stat.st_size),
            "modified": float(stat.st_mtime),
            "version": f"{int(stat.st_mtime_ns):x}-{int(stat.st_size):x}",
            "source_url": f"/api/emote-files/{source}/{encoded}",
            "download_url": f"/api/settings/emotes/{source}/{encoded}/download",
        }
        if preview_stat is not None:
            preview_version = f"{int(preview_stat.st_mtime_ns):x}-{int(preview_stat.st_size):x}"
            item.update({
                "preview_available": True,
                "preview_filename": preview_path.name,
                "preview_bytes": int(preview_stat.st_size),
                "preview_modified": float(preview_stat.st_mtime),
                "preview_version": preview_version,
                "preview_url": f"/api/emote-previews/{source}/{encoded}?v={preview_version}",
            })
        else:
            item.update({
                "preview_available": False,
                "preview_filename": "",
                "preview_bytes": 0,
                "preview_modified": 0.0,
                "preview_version": "",
                "preview_url": "",
            })
        self._cache = {
            key: value for key, value in self._cache.items()
            if key[0] != str(path)
        }
        self._cache[cache_key] = dict(item)
        return item

    def _all_from(self, root: Path, source: str) -> List[Dict[str, Any]]:
        if not root.is_dir():
            return []
        items: List[Dict[str, Any]] = []
        for path in sorted(root.iterdir(), key=lambda item: item.name.casefold()):
            if not path.is_file() or path.is_symlink() or path.suffix.lower() != ".json":
                continue
            try:
                self._filename(path.name)
                items.append(self._item(path, source))
            except (ValueError, OSError):
                continue
        return items

    def snapshot(self) -> Dict[str, Any]:
        with self._lock:
            standard = self._all_from(self.standard_root, "standard")
            user = self._all_from(self.root, "user")
            effective: Dict[str, Dict[str, Any]] = {item["name"]: item for item in standard}
            for item in user:
                item = dict(item)
                item["overrides_standard"] = item["name"] in effective
                effective[item["name"]] = item
            items = sorted(effective.values(), key=lambda item: (str(item["name"]).casefold(), str(item["filename"]).casefold()))
            return {
                "ok": True,
                "directory": str(self.root),
                "standard_directory": str(self.standard_root),
                "format": EMOTE_FORMAT,
                "user_count": len(user),
                "standard_count": len(standard),
                "emotes": items,
            }

    def upload(self, name_value: Any, stream, length: int, *, overwrite: bool = False) -> Dict[str, Any]:
        name, path = self._user_path(name_value)
        length = int(length)
        if length <= 0:
            raise ValueError("emote upload is empty")
        if length > MAX_EMOTE_BYTES:
            raise ValueError(f"emote is larger than {MAX_EMOTE_BYTES // (1024 * 1024)} MiB")
        with self._lock:
            if path.exists() and not overwrite:
                raise FileExistsError(f"emote already exists: {name}")
            fd, temp_name = tempfile.mkstemp(prefix=f".{name}.", suffix=".upload", dir=str(self.root))
            remaining = length
            temp = Path(temp_name)
            try:
                os.fchmod(fd, 0o600)
                with os.fdopen(fd, "wb", closefd=True) as output:
                    while remaining:
                        chunk = stream.read(min(1024 * 1024, remaining))
                        if not chunk:
                            raise ValueError("emote upload ended before Content-Length bytes were received")
                        output.write(chunk)
                        remaining -= len(chunk)
                    output.flush()
                    os.fsync(output.fileno())
                clip, _document = self._validate_path(temp)
                for other in self._all_from(self.root, "user"):
                    if other["filename"] != name and other["name"] == clip.name:
                        raise ValueError(
                            f"user emote name {clip.name!r} is already provided by {other['filename']}"
                        )
                os.replace(temp, path)
                os.chmod(path, 0o600)
                # A manual upload or an OpenBDX install replaces the runtime
                # without replacing its locally rendered preview. Remove any
                # stale sidecar so it cannot be published for the new bytes.
                self.preview_path_for(path).unlink(missing_ok=True)
            finally:
                try:
                    os.close(fd)
                except OSError:
                    pass
                try:
                    temp.unlink()
                except FileNotFoundError:
                    pass
            self._cache = {key: value for key, value in self._cache.items() if key[0] != str(path)}
            item = self._item(path, "user")
            return {"ok": True, "message": f"Uploaded {name}.", "emote": item}

    def delete(self, name_value: Any) -> Dict[str, Any]:
        name, path = self._user_path(name_value)
        with self._lock:
            if not path.is_file() or path.is_symlink():
                raise FileNotFoundError(name)
            path.unlink()
            self.preview_path_for(path).unlink(missing_ok=True)
            self._cache = {key: value for key, value in self._cache.items() if key[0] != str(path)}
        return {"ok": True, "message": f"Deleted {name}."}

    def preview_path(self, source_or_name: Any, name_value: Any = None) -> Path:
        # The one-argument form is retained for the connected-duck publisher,
        # which only publishes operator-owned emotes. The two-argument form is
        # used by the browser route and also permits future packaged previews.
        if name_value is None:
            name, path = self._user_path(source_or_name)
        else:
            _source, name, path = self._source_path(source_or_name, name_value)
        preview = self.preview_path_for(path)
        if not preview.is_file() or preview.is_symlink():
            raise FileNotFoundError(self.preview_filename(name))
        return preview

    def download_path(self, source: Any, name_value: Any) -> Path:
        _source, name, path = self._source_path(source, name_value)
        if not path.is_file() or path.is_symlink():
            raise FileNotFoundError(name)
        self._validate_path(path)
        return path


class EmotePlaygroundLauncher:
    """Launch Duckmation as a managed companion to the web UI.

    The editor remains a standalone Flask/Viser application. PuddleDuck only
    resolves a trusted input clip, chooses the user emote output directory,
    starts the process, and exposes its status to the browser.
    """

    DEFAULT_EDITOR_PORT = 5001
    DEFAULT_VIEWER_PORT = 5002
    DEFAULT_STARTUP_TIMEOUT = 60.0
    ROBOT_VARIANTS = {
        "besh": "Besh",
        "grek": "Grek",
        "oskar": "Oskar",
        "patch": "Patch",
        "red": "Red",
    }

    def __init__(
        self,
        emotes: EmoteLibrary,
        *,
        duckmation_root: Optional[str] = None,
        robots_dir: Optional[str] = None,
        command: Optional[str] = None,
        python_executable: Optional[str] = None,
        robot_variant: Optional[str] = None,
        editor_port: Optional[int] = None,
        viewer_port: Optional[int] = None,
        startup_timeout: Optional[float] = None,
        public_viewer_path: str = "/emote-playground-viewer/",
        popen_factory: Callable[..., Any] = subprocess.Popen,
    ):
        self.emotes = emotes
        self.duckmation_root = self._find_root(duckmation_root)
        self.robots_dir = self._find_robots_dir(robots_dir)
        self.command_override = str(
            command
            if command is not None
            else os.environ.get("PUDDLEDUCK_EMOTE_PLAYGROUND_COMMAND", "")
        ).strip()
        self.python_executable = str(
            python_executable
            if python_executable is not None
            else os.environ.get("PUDDLEDUCK_EMOTE_PLAYGROUND_PYTHON", "")
        ).strip()
        self.robot = str(
            os.environ.get("PUDDLEDUCK_EMOTE_PLAYGROUND_ROBOT", "darkwing4_bdx")
        ).strip() or "darkwing4_bdx"
        configured_variant = (
            robot_variant
            if robot_variant is not None
            else os.environ.get("PUDDLEDUCK_EMOTE_PLAYGROUND_ROBOT_VARIANT", "")
        )
        self.robot_variant = self._robot_variant(configured_variant)
        self.editor_port = self._port(
            editor_port
            if editor_port is not None
            else os.environ.get("PUDDLEDUCK_EMOTE_PLAYGROUND_PORT"),
            self.DEFAULT_EDITOR_PORT,
        )
        self.viewer_port = self._port(
            viewer_port
            if viewer_port is not None
            else os.environ.get("PUDDLEDUCK_EMOTE_VIEWER_PORT"),
            self.DEFAULT_VIEWER_PORT,
        )
        self.startup_timeout = self._timeout(
            startup_timeout
            if startup_timeout is not None
            else os.environ.get("PUDDLEDUCK_EMOTE_PLAYGROUND_START_TIMEOUT"),
            self.DEFAULT_STARTUP_TIMEOUT,
        )
        self.public_viewer_path = str(public_viewer_path or "/emote-playground-viewer/").strip()
        if not self.public_viewer_path.startswith("/"):
            self.public_viewer_path = "/" + self.public_viewer_path
        if not self.public_viewer_path.endswith("/"):
            self.public_viewer_path += "/"
        self._popen_factory = popen_factory
        self._process: Optional[Any] = None
        self._process_log = None
        self._last_command: List[str] = []
        self._last_error = ""
        self._last_started_at: Optional[float] = None
        self._mode = ""
        self._filename = ""
        self._active_robot_variant = ""
        self._lock = threading.RLock()
        self.log_path = Path(
            os.environ.get(
                "PUDDLEDUCK_EMOTE_PLAYGROUND_LOG",
                str(Path.home() / ".local" / "state" / "puddleduck" / "emote-playground.log"),
            )
        ).expanduser().resolve()

    @staticmethod
    def _port(value: Any, default: int) -> int:
        try:
            port = int(value)
        except (TypeError, ValueError):
            port = int(default)
        return port if 1 <= port <= 65535 else int(default)

    @staticmethod
    def _timeout(value: Any, default: float) -> float:
        try:
            timeout = float(value)
        except (TypeError, ValueError):
            timeout = float(default)
        return min(max(timeout, 1.0), 300.0)

    @classmethod
    def _robot_variant(cls, value: Any) -> str:
        text = str(value or "").strip()
        if not text or text.lower() == "auto":
            return ""
        variant = cls.ROBOT_VARIANTS.get(text.lower())
        if variant is None:
            allowed = ", ".join(cls.ROBOT_VARIANTS.values())
            raise ValueError(f"robot variant must be one of: {allowed}")
        return variant

    @staticmethod
    def _candidate_roots(explicit: Optional[str]) -> Iterable[Path]:
        values = [
            explicit,
            os.environ.get("PUDDLEDUCK_DUCKMATION_DIR"),
            "/usr/local/assets/Duckmation",
            str(Path.home() / "Duckmation"),
            "/opt/Duckmation",
        ]
        # Development checkout: PuddleDuck and Duckmation may be siblings.
        try:
            values.append(str(Path(__file__).resolve().parents[4] / "Duckmation"))
        except IndexError:
            pass
        seen = set()
        for value in values:
            text = str(value or "").strip()
            if not text:
                continue
            path = Path(text).expanduser().resolve()
            if str(path) in seen:
                continue
            seen.add(str(path))
            yield path

    def _find_robots_dir(self, explicit: Optional[str]) -> Optional[Path]:
        values = [
            explicit,
            os.environ.get("PUDDLEDUCK_DUCKMATION_ROBOTS_DIR"),
            os.environ.get("DUCKMATION_ROBOTS_DIR"),
            self.duckmation_root / "robots" if self.duckmation_root else None,
            "/usr/local/assets/robots",
        ]
        seen = set()
        for value in values:
            text = str(value or "").strip()
            if not text:
                continue
            path = Path(text).expanduser().resolve()
            if str(path) in seen:
                continue
            seen.add(str(path))
            if path.is_dir():
                return path
        return None

    @classmethod
    def _find_root(cls, explicit: Optional[str]) -> Optional[Path]:
        for root in cls._candidate_roots(explicit):
            if (root / "motion_generator" / "emote_playground.py").is_file():
                return root
        return None

    @property
    def script_path(self) -> Optional[Path]:
        if self.duckmation_root is None:
            return None
        return self.duckmation_root / "motion_generator" / "emote_playground.py"

    def _system_install(self) -> bool:
        root = self.duckmation_root
        if root is None:
            return False
        try:
            root.relative_to(Path("/usr/local/assets"))
            return True
        except ValueError:
            return False

    def _base_command(self) -> List[str]:
        if self.command_override:
            command = shlex.split(self.command_override)
            if not command:
                raise RuntimeError("PUDDLEDUCK_EMOTE_PLAYGROUND_COMMAND is empty")
            return command
        root = self.duckmation_root
        script = self.script_path
        if root is None or script is None:
            raise RuntimeError(
                "Duckmation was not found; set PUDDLEDUCK_DUCKMATION_DIR or "
                "PUDDLEDUCK_EMOTE_PLAYGROUND_COMMAND"
            )
        python = self.python_executable
        if not python:
            project_python = root / ".venv" / "bin" / "python"
            if not project_python.is_file():
                raise RuntimeError(
                    "Duckmation's Python environment is missing: "
                    f"{project_python}. Run uv sync in {root} or rebuild the image."
                )
            python = str(project_python)
        return [python, str(script)]

    def available(self) -> Tuple[bool, str]:
        if not self.command_override and self.robots_dir is None:
            return False, (
                "Duckmation robot assets were not found; set "
                "PUDDLEDUCK_DUCKMATION_ROBOTS_DIR or install /usr/local/assets/robots"
            )
        try:
            command = self._base_command()
        except Exception as exc:
            return False, str(exc)
        executable = command[0]
        if os.path.sep in executable:
            if not Path(executable).expanduser().is_file():
                return False, f"editor executable is missing: {executable}"
        elif shutil.which(executable) is None:
            return False, f"editor executable is not on PATH: {executable}"
        return True, ""

    def _preflight_environment(self, command: List[str]) -> None:
        """Fail early when the deployed Duckmation environment is incomplete."""
        if self.command_override or not self._system_install():
            return
        probe = (
            "import flask, numpy, placo, scipy, viser; "
            "import placo_utils.visualization"
        )
        try:
            completed = subprocess.run(
                [command[0], "-c", probe],
                cwd=str(self.duckmation_root),
                env={**os.environ, "PYTHONUNBUFFERED": "1"},
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                timeout=20.0,
                check=False,
            )
        except Exception as exc:
            raise RuntimeError(f"Duckmation environment preflight failed: {exc}") from exc
        if completed.returncode != 0:
            output = " ".join((completed.stdout or "").strip().splitlines()[-8:])
            detail = f": {output}" if output else ""
            raise RuntimeError(
                f"Duckmation environment preflight exited with status {completed.returncode}{detail}"
            )

    def _running_unlocked(self) -> bool:
        return bool(self._process is not None and self._process.poll() is None)

    def status(self) -> Dict[str, Any]:
        with self._lock:
            available, reason = self.available()
            running = self._running_unlocked()
            return {
                "available": available,
                "reason": reason,
                "running": running,
                "pid": int(self._process.pid) if running and getattr(self._process, "pid", None) else None,
                "mode": self._mode,
                "filename": self._filename,
                "robot": self.robot,
                "robot_variant": self._active_robot_variant or self.robot_variant,
                "editor_port": self.editor_port,
                "viewer_port": self.viewer_port,
                "startup_timeout": self.startup_timeout,
                "public_path": "/emote-playground/",
                "public_viewer_path": self.public_viewer_path,
                "duckmation_root": str(self.duckmation_root or ""),
                "robots_dir": str(self.robots_dir or ""),
                "log": str(self.log_path),
                "last_started_at": self._last_started_at,
                "last_error": self._last_error,
            }

    def _stop_unlocked(self) -> None:
        process = self._process
        self._process = None
        if process is not None and process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=4.0)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait(timeout=2.0)
        if self._process_log is not None:
            try:
                self._process_log.close()
            except Exception:
                pass
            self._process_log = None

    def stop(self) -> None:
        with self._lock:
            self._stop_unlocked()

    def _wait_until_started(self, timeout: Optional[float] = None) -> None:
        # Socket polling avoids importing Flask or assuming a particular health
        # response. Caddy/WebSocket proxying starts only after this port binds.
        import socket

        wait_seconds = self.startup_timeout if timeout is None else float(timeout)
        deadline = time.monotonic() + max(0.1, wait_seconds)
        last_error = ""
        while time.monotonic() < deadline:
            if self._process is not None and self._process.poll() is not None:
                raise RuntimeError(f"Emote Playground exited with status {self._process.returncode}")
            try:
                with socket.create_connection(("127.0.0.1", self.editor_port), timeout=0.25):
                    return
            except OSError as exc:
                last_error = str(exc)
                time.sleep(0.15)
        raise RuntimeError(
            f"Emote Playground did not open port {self.editor_port} within "
            f"{wait_seconds:g} seconds: {last_error}"
        )

    def _log_tail(self, max_bytes: int = 16384, max_lines: int = 16) -> str:
        try:
            if self._process_log is not None:
                self._process_log.flush()
            with self.log_path.open("rb") as stream:
                stream.seek(0, os.SEEK_END)
                size = stream.tell()
                stream.seek(max(0, size - max_bytes), os.SEEK_SET)
                text = stream.read().decode("utf-8", errors="replace")
        except Exception:
            return ""
        lines = [line.strip() for line in text.splitlines() if line.strip()]
        return " | ".join(lines[-max_lines:])

    def launch(
        self,
        *,
        mode: str,
        initial_file: Optional[Path] = None,
        managed_filename: str = "",
        robot_variant: Optional[str] = None,
    ) -> Dict[str, Any]:
        mode = str(mode or "").strip().lower()
        if mode not in {"new", "edit"}:
            raise ValueError("editor mode must be new or edit")
        if mode == "edit" and initial_file is None:
            raise ValueError("Edit requires an emote file")
        if managed_filename:
            managed_filename = EmoteLibrary._filename(managed_filename)
        requested_variant = self._robot_variant(
            self.robot_variant
            if robot_variant is None or str(robot_variant).strip() == ""
            else robot_variant
        )

        with self._lock:
            available, reason = self.available()
            if not available:
                self._last_error = reason
                raise RuntimeError(reason)
            self._stop_unlocked()
            command = self._base_command()
            try:
                self._preflight_environment(command)
            except Exception as exc:
                self._last_error = str(exc)
                raise RuntimeError(str(exc)) from exc
            command.extend(
                [
                    "--robot", self.robot,
                    "--host", "0.0.0.0",
                    "--port", str(self.editor_port),
                    "--viser-host", "0.0.0.0",
                    "--viser-port", str(self.viewer_port),
                    "--no-browser",
                    "--managed-output-dir", str(self.emotes.root),
                    "--public-viewer-path", self.public_viewer_path,
                ]
            )
            if self.robots_dir is not None:
                command.extend(["--robots-dir", str(self.robots_dir)])
            if requested_variant:
                command.extend(["--robot-variant", requested_variant])
            if initial_file is not None:
                command.extend(["--initial-file", str(initial_file.resolve())])
            if managed_filename:
                command.extend(["--managed-filename", managed_filename])

            self.log_path.parent.mkdir(parents=True, exist_ok=True)
            self._process_log = self.log_path.open("a", encoding="utf-8")
            self._process_log.write(
                f"\n[{time.strftime('%Y-%m-%d %H:%M:%S')}] launching "
                f"{' '.join(shlex.quote(part) for part in command)}\n"
            )
            self._process_log.flush()
            environment = os.environ.copy()
            environment["PYTHONUNBUFFERED"] = "1"
            self._last_command = list(command)
            self._last_error = ""
            self._mode = mode
            self._filename = managed_filename
            self._active_robot_variant = requested_variant
            self._last_started_at = time.time()
            try:
                self._process = self._popen_factory(
                    command,
                    cwd=str(self.duckmation_root) if self.duckmation_root else None,
                    env=environment,
                    stdin=subprocess.DEVNULL,
                    stdout=self._process_log,
                    stderr=subprocess.STDOUT,
                    start_new_session=True,
                )
                self._wait_until_started()
            except Exception as exc:
                self._stop_unlocked()
                tail = self._log_tail()
                detail = str(exc)
                if tail:
                    detail = f"{detail}. Duckmation log: {tail}"
                self._last_error = detail
                raise RuntimeError(detail) from exc
            status = self.status()
            status.update({"ok": True, "message": f"Emote Playground started in {mode} mode."})
            return status

_SOUND_COMPONENT_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._ ()+-]{0,159}$")
_SOUND_EXTENSIONS = {".wav", ".mp3", ".ogg", ".oga", ".opus", ".flac", ".m4a", ".aac"}
MAX_SOUND_BYTES = 128 * 1024 * 1024


class SoundLibrary:
    """Operator-owned sound library under ``$HOME/sounds``.

    Relative subdirectories are supported so trigger actions can use categories
    such as ``duck/`` or ``curious/``.  All paths are validated component by
    component and are kept beneath the configured root.
    """

    def __init__(self, root: Optional[str] = None):
        self.root = Path(root or "~/sounds").expanduser()
        self.root.mkdir(parents=True, exist_ok=True)
        self._lock = threading.RLock()
        self._meta_cache: Dict[str, Tuple[int, int, Dict[str, Any]]] = {}

    @staticmethod
    def _relative(value: Any, *, sound_file: bool = True, allow_empty: bool = False) -> str:
        text = str(value or "").strip().replace("\\", "/")
        if not text:
            if allow_empty:
                return ""
            raise ValueError("sound path may not be empty")
        candidate = Path(text)
        if candidate.is_absolute() or any(part in ("", ".", "..") for part in candidate.parts):
            raise ValueError("sound path must be relative and may not contain '.' or '..'")
        if len(candidate.parts) > 12:
            raise ValueError("sound path has too many directory levels")
        for component in candidate.parts:
            if not _SOUND_COMPONENT_RE.fullmatch(component):
                raise ValueError(f"unsupported sound path component: {component!r}")
        if sound_file and candidate.suffix.lower() not in _SOUND_EXTENSIONS:
            raise ValueError("sound must be WAV, MP3, Ogg, Opus, FLAC, M4A, or AAC")
        return candidate.as_posix()

    def path(self, name_value: Any) -> Path:
        relative = self._relative(name_value, sound_file=True)
        path = (self.root / relative).resolve()
        try:
            path.relative_to(self.root.resolve())
        except ValueError as exc:
            raise ValueError("sound path escapes the sounds directory") from exc
        return path

    def directory(self, value: Any) -> Path:
        relative = self._relative(value, sound_file=False, allow_empty=True)
        path = (self.root / relative).resolve() if relative else self.root.resolve()
        try:
            path.relative_to(self.root.resolve())
        except ValueError as exc:
            raise ValueError("sound directory escapes the sounds directory") from exc
        return path

    @staticmethod
    def _wav_info(path: Path) -> Dict[str, Any]:
        try:
            with wave.open(str(path), "rb") as source:
                frames = int(source.getnframes())
                rate = int(source.getframerate())
                channels = int(source.getnchannels())
                width = int(source.getsampwidth())
            return {
                "duration_s": (frames / rate) if rate > 0 else None,
                "sample_rate": rate,
                "channels": channels,
                "sample_width_bits": width * 8,
                "codec": f"PCM {width * 8}-bit",
            }
        except Exception:
            return {}

    @staticmethod
    def _ffprobe_info(path: Path) -> Dict[str, Any]:
        ffprobe = shutil.which("ffprobe")
        if not ffprobe:
            return {}
        try:
            completed = subprocess.run(
                [
                    ffprobe,
                    "-v", "error",
                    "-select_streams", "a:0",
                    "-show_entries", "stream=codec_name,sample_rate,channels:format=duration",
                    "-of", "json",
                    str(path),
                ],
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL,
                text=True,
                timeout=4.0,
                check=False,
            )
            value = json.loads(completed.stdout or "{}") if completed.returncode == 0 else {}
            streams = value.get("streams") if isinstance(value, dict) else []
            stream = streams[0] if isinstance(streams, list) and streams and isinstance(streams[0], dict) else {}
            fmt = value.get("format") if isinstance(value, dict) and isinstance(value.get("format"), dict) else {}
            result: Dict[str, Any] = {}
            try:
                result["duration_s"] = float(fmt.get("duration"))
            except Exception:
                pass
            try:
                result["sample_rate"] = int(stream.get("sample_rate"))
            except Exception:
                pass
            try:
                result["channels"] = int(stream.get("channels"))
            except Exception:
                pass
            if stream.get("codec_name"):
                result["codec"] = str(stream["codec_name"])
            return result
        except Exception:
            return {}

    def _item(self, path: Path) -> Dict[str, Any]:
        st = path.stat()
        relative = path.relative_to(self.root).as_posix()
        cached = self._meta_cache.get(relative)
        if cached and cached[0] == int(st.st_mtime_ns) and cached[1] == int(st.st_size):
            extra = dict(cached[2])
        else:
            extra = self._wav_info(path) if path.suffix.lower() == ".wav" else self._ffprobe_info(path)
            self._meta_cache[relative] = (int(st.st_mtime_ns), int(st.st_size), dict(extra))
        mime = mimetypes.guess_type(path.name)[0] or "application/octet-stream"
        quoted = quote(relative, safe="/")
        return {
            "name": relative,
            "basename": path.name,
            "directory": path.parent.relative_to(self.root).as_posix() if path.parent != self.root else "",
            "bytes": int(st.st_size),
            "modified": float(st.st_mtime),
            "mime": mime,
            "playable": path.suffix.lower() in _SOUND_EXTENSIONS,
            "url": f"/api/settings/audio/sounds/{quoted}",
            "download_url": f"/api/settings/audio/sounds/{quoted}?download=1",
            **extra,
        }

    def snapshot(self, directory_value: Any = "") -> Dict[str, Any]:
        """Return one directory level for the browser sound navigator."""
        with self._lock:
            current_path = self.directory(directory_value)
            if not current_path.is_dir():
                raise FileNotFoundError(str(directory_value or ""))
            current = current_path.relative_to(self.root).as_posix() if current_path != self.root else ""
            parent_path = current_path.parent
            parent = (
                parent_path.relative_to(self.root).as_posix()
                if current_path != self.root and parent_path != self.root
                else ""
            )
            directories: List[Dict[str, Any]] = []
            items: List[Dict[str, Any]] = []
            for path in sorted(current_path.iterdir(), key=lambda item: (not item.is_dir(), item.name.casefold())):
                if path.name.startswith(".") or path.is_symlink():
                    continue
                if path.is_dir():
                    relative = path.relative_to(self.root).as_posix()
                    try:
                        child_count = sum(
                            1 for child in path.iterdir()
                            if not child.name.startswith(".")
                            and not child.is_symlink()
                            and (child.is_dir() or (child.is_file() and child.suffix.lower() in _SOUND_EXTENSIONS))
                        )
                    except OSError:
                        child_count = 0
                    directories.append({
                        "name": relative,
                        "basename": path.name,
                        "child_count": child_count,
                    })
                    continue
                if path.is_file() and path.suffix.lower() in _SOUND_EXTENSIONS:
                    try:
                        items.append(self._item(path))
                    except OSError:
                        continue
            return {
                "ok": True,
                "directory": str(self.root),
                "current": current,
                "parent": parent,
                "at_root": current == "",
                "directories": directories,
                "items": items,
            }

    def upload(self, name_value: Any, stream, length: int, *, overwrite: bool = False) -> Dict[str, Any]:
        relative = self._relative(name_value, sound_file=True)
        length = int(length)
        if length <= 0:
            raise ValueError("sound upload is empty")
        if length > MAX_SOUND_BYTES:
            raise ValueError(f"sound is larger than {MAX_SOUND_BYTES // (1024 * 1024)} MiB")
        path = self.path(relative)
        with self._lock:
            if path.exists() and not overwrite:
                raise FileExistsError(f"sound already exists: {relative}")
            path.parent.mkdir(parents=True, exist_ok=True)
            fd, temp_name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".upload", dir=str(path.parent))
            remaining = length
            try:
                os.fchmod(fd, 0o600)
                with os.fdopen(fd, "wb", closefd=True) as output:
                    while remaining:
                        chunk = stream.read(min(1024 * 1024, remaining))
                        if not chunk:
                            raise ValueError("sound upload ended before Content-Length bytes were received")
                        output.write(chunk)
                        remaining -= len(chunk)
                    output.flush()
                    os.fsync(output.fileno())
                os.replace(temp_name, path)
                os.chmod(path, 0o600)
            except Exception:
                try:
                    os.close(fd)
                except OSError:
                    pass
                try:
                    os.unlink(temp_name)
                except OSError:
                    pass
                raise
            self._meta_cache.pop(relative, None)
            return {"ok": True, "message": f"Uploaded {relative}.", "item": self._item(path)}

    def delete(self, name_value: Any) -> Dict[str, Any]:
        relative = self._relative(name_value, sound_file=True)
        path = self.path(relative)
        with self._lock:
            if not path.is_file():
                raise FileNotFoundError(relative)
            path.unlink()
            self._meta_cache.pop(relative, None)
            parent = path.parent
            root = self.root.resolve()
            while parent != root:
                try:
                    parent.rmdir()
                except OSError:
                    break
                parent = parent.parent
        return {"ok": True, "message": f"Deleted {relative}."}

    def choose(self, directory_value: Any, *, recursive: bool = False) -> str:
        directory = self.directory(directory_value)
        if not directory.is_dir():
            raise FileNotFoundError(str(directory_value))
        iterator = directory.rglob("*") if recursive else directory.iterdir()
        choices = [
            path for path in iterator
            if path.is_file() and path.suffix.lower() in _SOUND_EXTENSIONS
        ]
        if not choices:
            raise FileNotFoundError(f"no sound files found in {directory_value}")
        return random.choice(choices).relative_to(self.root).as_posix()


class LocalSoundPlayer:
    """Fire-and-forget playback through the Orin user's default audio server."""

    def __init__(self, library: SoundLibrary):
        self.library = library

    @staticmethod
    def _command(path: Path) -> List[str]:
        for candidate in (["paplay"], ["pw-play"], ["aplay", "-q"]):
            if shutil.which(candidate[0]):
                return candidate + [str(path)]
        raise RuntimeError("no paplay, pw-play, or aplay command is installed")

    def play(self, relative_name: Any) -> Dict[str, Any]:
        path = self.library.path(relative_name)
        if not path.is_file():
            raise FileNotFoundError(str(relative_name))
        command = self._command(path)
        process = subprocess.Popen(
            command,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            start_new_session=True,
        )
        threading.Thread(target=process.wait, name="body-sound-reaper", daemon=True).start()
        return {"ok": True, "name": path.relative_to(self.library.root).as_posix(), "message": f"Playing {path.name} on body."}


class BluetoothManager:
    """Best-effort BlueZ administration through the installed bluetoothctl."""

    def __init__(
        self,
        executable: Optional[str] = None,
        *,
        on_controller_paired: Optional[Callable[[Dict[str, Any]], Dict[str, Any]]] = None,
    ):
        self.executable = executable or shutil.which("bluetoothctl") or ""
        self._lock = threading.Lock()
        self._on_controller_paired = on_controller_paired

    @property
    def available(self) -> bool:
        return bool(self.executable and Path(self.executable).exists())

    def _run(self, args: Iterable[str], *, input_text: Optional[str] = None, timeout: float = 12.0) -> subprocess.CompletedProcess:
        if not self.available:
            raise RuntimeError("bluetoothctl is not installed")
        try:
            return subprocess.run(
                [self.executable, *[str(v) for v in args]],
                input=input_text,
                text=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                timeout=max(1.0, float(timeout)),
                check=False,
                env={**os.environ, "LC_ALL": "C"},
            )
        except subprocess.TimeoutExpired as exc:
            output = str(exc.stdout or "")
            return subprocess.CompletedProcess([self.executable, *args], 124, output)

    def _batch(self, commands: Iterable[str], *, timeout: float = 25.0) -> str:
        text = "\n".join(str(v) for v in commands) + "\nquit\n"
        result = self._run([], input_text=text, timeout=timeout)
        output = self._clean_output(result.stdout)
        if result.returncode not in (0, 124) and not output:
            raise RuntimeError(f"bluetoothctl failed with status {result.returncode}")
        return output

    @staticmethod
    def _clean_output(value: Any) -> str:
        return _clean_bluetoothctl_output(value)

    def _pairing_agent(self) -> _BluetoothctlPairingAgent:
        return _BluetoothctlPairingAgent(self.executable)

    @classmethod
    def _failure_detail(cls, value: Any) -> str:
        """Return the useful BlueZ failure instead of bluetoothctl's prompt."""
        lines = []
        for raw in cls._clean_output(value).splitlines():
            line = raw.strip()
            if not line or _BT_PROMPT_RE.fullmatch(line):
                continue
            lines.append(line)

        failure_tokens = (
            "failed", "error", "authentication", "rejected", "canceled",
            "cancelled", "not available", "not found", "not ready",
            "connection attempt", "org.bluez",
        )
        for line in reversed(lines):
            lowered = line.lower()
            if any(token in lowered for token in failure_tokens):
                return line

        ignored_prefixes = (
            "attempting to pair", "agent registered", "default agent",
            "changing power", "[chg]", "[new]", "[del]",
        )
        for line in reversed(lines):
            if not line.lower().startswith(ignored_prefixes):
                return line
        return "pairing did not complete"

    @staticmethod
    def _parse_properties(text: str) -> Dict[str, str]:
        props: Dict[str, str] = {}
        for raw in BluetoothManager._clean_output(text).splitlines():
            line = raw.strip()
            if ":" not in line:
                continue
            key, value = line.split(":", 1)
            key = key.strip()
            if key and key not in props:
                props[key] = value.strip()
        return props

    @staticmethod
    def _yes(value: Any) -> bool:
        return str(value or "").strip().lower() in ("yes", "true", "1", "on")

    @staticmethod
    def _kind(props: Dict[str, str]) -> str:
        icon = str(props.get("Icon") or "").lower()
        name = str(props.get("Name") or props.get("Alias") or "").lower()
        identity = f"{icon} {name}"
        if any(token in identity for token in (
            "input", "joystick", "gamepad", "controller", "keyboard", "mouse", "input-gaming",
        )):
            return "controller"
        if any(token in identity for token in (
            "audio", "headset", "headphone", "speaker", "microphone",
        )):
            return "audio"

        uuid = str(props.get("UUID") or "").lower()
        device_class = str(props.get("Class") or "").lower()
        capabilities = f"{uuid} {device_class}"
        if any(token in capabilities for token in ("human interface", "00001124")):
            return "controller"
        if any(token in capabilities for token in ("0000110b", "0000110e", "0000111e")):
            return "audio"
        return "other"

    def _device_info(self, address: str, fallback_name: str = "") -> Dict[str, Any]:
        result = self._run(["info", address], timeout=4)
        props = self._parse_properties(result.stdout)
        name = props.get("Name") or props.get("Alias") or fallback_name or address
        return {
            "address": address.upper(),
            "name": name,
            "alias": props.get("Alias") or name,
            "icon": props.get("Icon") or "",
            "kind": self._kind(props),
            "paired": self._yes(props.get("Paired")),
            "trusted": self._yes(props.get("Trusted")),
            "connected": self._yes(props.get("Connected")),
            "blocked": self._yes(props.get("Blocked")),
            "rssi": props.get("RSSI"),
        }

    def snapshot(self) -> Dict[str, Any]:
        with self._lock:
            if not self.available:
                return {"ok": True, "available": False, "message": "bluetoothctl is not installed", "devices": []}
            show = self._run(["show"], timeout=4)
            controller = self._parse_properties(show.stdout)
            devices_result = self._run(["devices"], timeout=5)
            discovered: Dict[str, str] = {}
            for raw in self._clean_output(devices_result.stdout).splitlines():
                line = raw.strip()
                match = re.match(r"^Device\s+([0-9A-Fa-f:]{17})\s*(.*)$", line)
                if match:
                    discovered[match.group(1).upper()] = match.group(2).strip()
            devices = []
            for address, name in list(discovered.items())[:64]:
                try:
                    devices.append(self._device_info(address, name))
                except Exception:
                    devices.append({
                        "address": address,
                        "name": name or address,
                        "alias": name or address,
                        "icon": "",
                        "kind": "other",
                        "paired": False,
                        "trusted": False,
                        "connected": False,
                        "blocked": False,
                        "rssi": None,
                    })
            devices.sort(key=lambda item: (not item["connected"], not item["paired"], str(item["name"]).lower()))
            return {
                "ok": True,
                "available": True,
                "controller": {
                    "name": controller.get("Name") or controller.get("Alias") or "Bluetooth",
                    "address": controller.get("Controller") or "",
                    "powered": self._yes(controller.get("Powered")),
                    "discovering": self._yes(controller.get("Discovering")),
                    "pairable": self._yes(controller.get("Pairable")),
                },
                "devices": devices,
            }

    def scan(self, seconds: int = 8) -> Dict[str, Any]:
        seconds = max(3, min(int(seconds or 8), 30))
        with self._lock:
            if not self.available:
                raise RuntimeError("bluetoothctl is not installed")
            # --timeout is supported by the BlueZ bluetoothctl shipped on the Orins.
            # If it is not, the subprocess timeout still bounds the operation.
            result = self._run(["--timeout", str(seconds), "scan", "on"], timeout=seconds + 4)
            output = str(result.stdout or "")
            if "Invalid option" in output or "unknown option" in output.lower():
                self._batch(["power on", "scan on"], timeout=seconds)
        snap = self.snapshot()
        snap["message"] = f"Bluetooth scan complete ({seconds}s)"
        return snap

    def mutate(self, action: str, address: str) -> Dict[str, Any]:
        action = str(action or "").strip().lower()
        address = str(address or "").strip().upper()
        if not _BT_ADDRESS_RE.fullmatch(address):
            raise ValueError("invalid Bluetooth address")
        with self._lock:
            if not self.available:
                raise RuntimeError("bluetoothctl is not installed")
            if action == "pair":
                power_result = self._run(["power", "on"], timeout=8)
                agent = self._pairing_agent()
                try:
                    agent.register_default()
                    agent.send(f"pair {address}")
                    deadline = time.monotonic() + 30.0
                    paired_info = None
                    while time.monotonic() < deadline:
                        try:
                            paired_info = self._device_info(address)
                        except Exception:
                            paired_info = None
                        if paired_info and paired_info.get("paired"):
                            break
                        transcript = agent.transcript()
                        lowered = transcript.lower()
                        if any(token in lowered for token in (
                            "failed to pair",
                            "org.bluez.error",
                            "authenticationfailed",
                            "authenticationrejected",
                            "authenticationcanceled",
                        )):
                            break
                        if agent.process.poll() is not None:
                            break
                        time.sleep(0.25)
                    output = "\n".join(
                        part for part in (
                            self._clean_output(power_result.stdout).strip(),
                            agent.transcript(),
                        ) if part
                    )
                finally:
                    agent.close()
            elif action in ("connect", "disconnect", "trust", "untrust", "remove"):
                output = self._batch([f"{action} {address}"], timeout=18)
            else:
                raise ValueError(f"unknown Bluetooth action: {action}")
        if action == "pair":
            if paired_info is None:
                # BlueZ can publish the Paired property a fraction of a second
                # after bluetoothctl exits. Poll the one device briefly before
                # deciding that pairing failed or creating its mapping template.
                for _ in range(8):
                    try:
                        paired_info = self._device_info(address)
                    except Exception:
                        paired_info = None
                    if paired_info and paired_info.get("paired"):
                        break
                    time.sleep(0.25)

            if paired_info and paired_info.get("paired"):
                follow_up = []
                for command, timeout in (("trust", 8), ("connect", 15)):
                    result = self._run([command, address], timeout=timeout)
                    detail = self._clean_output(result.stdout).strip()
                    if detail:
                        follow_up.append(detail)
                if follow_up:
                    output = "\n".join(part for part in (output, *follow_up) if part)

        snapshot = self.snapshot()
        snapshot["message"] = f"Bluetooth {action} requested for {address}"
        snapshot["output"] = output[-4000:]

        if action == "pair":
            snapshot_device = next(
                (
                    item for item in snapshot.get("devices", [])
                    if str(item.get("address") or "").upper() == address
                ),
                None,
            )
            paired = (
                snapshot_device
                if snapshot_device and snapshot_device.get("paired")
                else paired_info or snapshot_device
            )
            if paired is None or not paired.get("paired"):
                detail = self._failure_detail(output)
                raise RuntimeError(f"Bluetooth pairing failed for {address}: {detail}")
            if paired.get("kind") == "controller" and self._on_controller_paired is not None:
                try:
                    template = self._on_controller_paired(dict(paired))
                    snapshot["controller_template"] = template
                    if template.get("created"):
                        snapshot["message"] = (
                            f"Paired {paired.get('name') or address}; created {template.get('filename') or template.get('name')}"
                        )
                except Exception as exc:
                    snapshot["controller_template"] = {
                        "ok": False,
                        "created": False,
                        "message": f"paired, but controller template creation failed: {exc}",
                    }
                    snapshot["message"] = snapshot["controller_template"]["message"]
        return snapshot
